        if normalized_name in py_module_names:
            return
        py_module_names.add(normalized_name)
        py_module_cache[normalized_name] = (locator.source_code, locator.source_path)
        if locator.output_path not in zf.namelist():
            zf.writestr(locator.output_path, locator.source_code)
        display.vvvvv('Using module_utils file %s' % to_text(locator.source_path, errors='surrogate_or_strict'))
