                                                  child_is_redirected=child_is_redirected)
            else:
                locator = CollectionModuleUtilLocator(parent, child_is_redirected=child_is_redirected)
            if not locator.found or not locator.is_package:
                # Namespace packages without an initializer still need a file in
                # the remote payload, even at intermediate levels.
                locator._set_result(parent, b'', '<generated>', True)
            add_locator(locator)

