            elif parts[:3] == ('ansible', 'module_utils', 'six'):
                parts = ('ansible', 'module_utils', 'six')
            if parts[:2] == ('ansible', 'module_utils'):
                locator = LegacyModuleUtilLocator(parts, is_ambiguous=True, mu_paths=module_utils_paths)
            elif parts[:1] == ('ansible_collections',) and len(parts) >= 3:
                locator = CollectionModuleUtilLocator(parts, is_ambiguous=True)
            else:
                display.warning('ModuleDepFinder improperly found a non-module_utils import %s' % (parts,))
                continue
            if not locator.found:
                raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                   (current_fqn, ', '.join(locator.candidate_names_joined())))
            resolved_parts = locator.normalized_name[:-1] if locator.is_package else locator.normalized_name
            add_parents(resolved_parts, locator.redirected)
            add_locator(locator)
