                    raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                       (current_fqn, ', '.join(target_locator.candidate_names_joined())))
                target_parts = (target_locator.normalized_name[:-1] if target_locator.is_package
                                else target_locator.normalized_name)
                add_parents(target_parts, target_locator.redirected)
                add_locator(target_locator)
        # Once scanned, source is held by the zip payload and can leave the cache.
        current_parts = tuple(current_fqn.split('.'))
        py_module_cache.pop(current_parts, None)
